window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d48520e64d4f0084"]={"versions": [{"id": "FIG-d48520e64d4f0084", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung der statischen Schnittstellenarchitektur für Callback-Funktionen des Diagnostic Communication Managers (DCM) innerhalb der AUTOSAR Classic Platform (Release 3.1.5). Das Diagramm verortet das BSW-Modul DCM im Kommunikations- und System-Stack und visualisiert die Interaktionsgrenzen zu den Nachbarmodulen PDU Router (PduR) auf Vermittlungsebene sowie Communication Manager (ComM) auf Systemmanagementebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Module («module»):</strong></li>\n<li><code>Dcm</code>: Implementiert und realisiert die Callback-Schnittstellen zur Verarbeitung von PDU-Übertragungen und Kommunikationsstatusänderungen.</li>\n<li><code>PduR</code>: Nutzt die Callback-Schnittstelle des DCM zur PDU-Puffer- und Statusbehandlung.</li>\n<li><code>ComM</code>: Nutzt die Callback-Schnittstelle des DCM zur Signalisierung von Netzwerkzuständen.</li>\n<li><strong>Schnittstellen («interface»):</strong></li>\n<li><code>Dcm_PduR</code>: Enthält Callback-Operationen für den PDU-Datenaustausch:</li>\n<li><code>Dcm_ProvideRxBuffer()</code></li>\n<li><code>Dcm_ProvideTxBuffer()</code></li>\n<li><code>Dcm_RxIndication()</code></li>\n<li><code>Dcm_TxConfirmation()</code></li>\n<li><code>Dcm_ComM</code>: Enthält Callback-Operationen für Kommunikationsmoduswechsel:</li>\n<li><code>Dcm_ComM_NoComModeEntered()</code></li>\n<li><code>Dcm_ComM_SilentComModeEntered()</code></li>\n<li><code>Dcm_ComM_FullComModeEntered()</code></li>\n<li><strong>Beziehungen:</strong></li>\n<li><code>Dcm</code> realisiert (<code>«realize»</code>) <code>Dcm_PduR</code> und <code>Dcm_ComM</code>.</li>\n<li><code>PduR</code> greift über eine gerichtete Abhängigkeit mit dem Stereotyp <code>«optional»</code> auf <code>Dcm_PduR</code> zu.</li>\n<li><code>ComM</code> greift über eine gerichtete Abhängigkeit auf <code>Dcm_ComM</code> zu.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Darstellung ereignisgesteuerter Callback-Abläufe:</p>\n<ul class=\"fig-list\">\n<li><strong>PDU-Verarbeitung (PduR -> Dcm):</strong> Beim Empfang einer Diagnose-PDU fordert der PduR mittels <code>Dcm_ProvideRxBuffer()</code> linearen Empfangspuffer an und meldet die Fertigstellung über <code>Dcm_RxIndication()</code>. Bei Diagnosesendeoperationen fordert der PduR Pufferinhalte über <code>Dcm_ProvideTxBuffer()</code> ab und bestätigt die Übertragung per <code>Dcm_TxConfirmation()</code>.</li>\n<li><strong>Modusverwaltung (ComM -> Dcm):</strong> Der ComM meldet Änderungen des Kommunikationszustands eines Kanals über <code>Dcm_ComM_NoComModeEntered()</code>, <code>Dcm_ComM_SilentComModeEntered()</code> oder <code>Dcm_ComM_FullComModeEntered()</code>, woraufhin das DCM Diagnosesitzungen, Timer und Kommunikationsfreigaben entsprechend synchronisiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich ist die Implementierung der Schnittstellenfunktionen durch das DCM-Modul gemäß AUTOSAR-SWS-DCM.</p>\n<ul class=\"fig-list\">\n<li>Die Abhängigkeit von <code>PduR</code> zu <code>Dcm_PduR</code> ist als <code>«optional»</code> deklariert, was die Möglichkeit widerspiegelt, Diagnoseschnittstellen modular zu konfigurieren (etwa wenn kein PduR-Routing erforderlich ist).</li>\n<li>Bei Einsatz des Standard-BSW-Stacks müssen die Funktionssignaturen und C-Prototypen exakt der AUTOSAR-Spezifikation für PduR- und ComM-Callback-APIs entsprechen.</li>\n<li>Die Benachrichtigungen durch ComM sind zwingend erforderlich, um bei inaktiver Kommunikation (NoCom) oder reiner Abhörbereitschaft (SilentCom) unzulässige Diagnoseaktivitäten zu unterbinden.</li>\n</ul>"}, {"id": "FIG-05eb9693d7f9fb59", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung der statischen Schnittstellenarchitektur für Callback-Funktionen des Diagnostic Communication Managers (DCM) innerhalb der AUTOSAR Classic Platform (Release 3.1.5). Das Diagramm verortet das BSW-Modul DCM im Kommunikations- und System-Stack und visualisiert die Interaktionsgrenzen zu den Nachbarmodulen PDU Router (PduR) auf Vermittlungsebene sowie Communication Manager (ComM) auf Systemmanagementebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Module («module»):</strong></li>\n<li><code>Dcm</code>: Implementiert und realisiert die Callback-Schnittstellen zur Verarbeitung von PDU-Übertragungen und Kommunikationsstatusänderungen.</li>\n<li><code>PduR</code>: Nutzt die Callback-Schnittstelle des DCM zur PDU-Puffer- und Statusbehandlung.</li>\n<li><code>ComM</code>: Nutzt die Callback-Schnittstelle des DCM zur Signalisierung von Netzwerkzuständen.</li>\n<li><strong>Schnittstellen («interface»):</strong></li>\n<li><code>Dcm_PduR</code>: Enthält Callback-Operationen für den PDU-Datenaustausch:</li>\n<li><code>Dcm_ProvideRxBuffer()</code></li>\n<li><code>Dcm_ProvideTxBuffer()</code></li>\n<li><code>Dcm_RxIndication()</code></li>\n<li><code>Dcm_TxConfirmation()</code></li>\n<li><code>Dcm_ComM</code>: Enthält Callback-Operationen für Kommunikationsmoduswechsel:</li>\n<li><code>Dcm_ComM_NoComModeEntered()</code></li>\n<li><code>Dcm_ComM_SilentComModeEntered()</code></li>\n<li><code>Dcm_ComM_FullComModeEntered()</code></li>\n<li><strong>Beziehungen:</strong></li>\n<li><code>Dcm</code> realisiert (<code>«realize»</code>) <code>Dcm_PduR</code> und <code>Dcm_ComM</code>.</li>\n<li><code>PduR</code> greift über eine gerichtete Abhängigkeit mit dem Stereotyp <code>«optional»</code> auf <code>Dcm_PduR</code> zu.</li>\n<li><code>ComM</code> greift über eine gerichtete Abhängigkeit auf <code>Dcm_ComM</code> zu.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Darstellung ereignisgesteuerter Callback-Abläufe:</p>\n<ul class=\"fig-list\">\n<li><strong>PDU-Verarbeitung (PduR -> Dcm):</strong> Beim Empfang einer Diagnose-PDU fordert der PduR mittels <code>Dcm_ProvideRxBuffer()</code> linearen Empfangspuffer an und meldet die Fertigstellung über <code>Dcm_RxIndication()</code>. Bei Diagnosesendeoperationen fordert der PduR Pufferinhalte über <code>Dcm_ProvideTxBuffer()</code> ab und bestätigt die Übertragung per <code>Dcm_TxConfirmation()</code>.</li>\n<li><strong>Modusverwaltung (ComM -> Dcm):</strong> Der ComM meldet Änderungen des Kommunikationszustands eines Kanals über <code>Dcm_ComM_NoComModeEntered()</code>, <code>Dcm_ComM_SilentComModeEntered()</code> oder <code>Dcm_ComM_FullComModeEntered()</code>, woraufhin das DCM Diagnosesitzungen, Timer und Kommunikationsfreigaben entsprechend synchronisiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich ist die Implementierung der Schnittstellenfunktionen durch das DCM-Modul gemäß AUTOSAR-SWS-DCM.</p>\n<ul class=\"fig-list\">\n<li>Die Abhängigkeit von <code>PduR</code> zu <code>Dcm_PduR</code> ist als <code>«optional»</code> deklariert, was die Möglichkeit widerspiegelt, Diagnoseschnittstellen modular zu konfigurieren (etwa wenn kein PduR-Routing erforderlich ist).</li>\n<li>Bei Einsatz des Standard-BSW-Stacks müssen die Funktionssignaturen und C-Prototypen exakt der AUTOSAR-Spezifikation für PduR- und ComM-Callback-APIs entsprechen.</li>\n<li>Die Benachrichtigungen durch ComM sind zwingend erforderlich, um bei inaktiver Kommunikation (NoCom) oder reiner Abhörbereitschaft (SilentCom) unzulässige Diagnoseaktivitäten zu unterbinden.</li>\n</ul>"}], "trans": [{"from": "FIG-d48520e64d4f0084", "to": "FIG-05eb9693d7f9fb59", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Diagrammrahmen</strong>: Der äußere UML-Rahmen (<code>class DCMCallbacks</code>) wurde entfernt.</li>\n<li><strong>Interface <code>Dcm_ComM</code></strong>: Die Reihenfolge der deklarierten Operationen wurde alphabetisch sortiert (neu: <code>Dcm_ComM_FullComModeEntered()</code>, <code>Dcm_ComM_NoComModeEntered()</code>, <code>Dcm_ComM_SilentComModeEntered()</code>; zuvor beginnend mit <code>Dcm_ComM_NoComModeEntered()</code>).</li>\n</ul>"}]};
